  ('builder-native-searcher-pipelines-aggregated', 'Builder-Native Searcher Pipelines (Aggregated)', 'core-protocol-architecture', 'mev-block-builders', 'N/A', ARRAY[]::text[], ARRAY[]::text[], '{"description": "Searcher infrastructure embedded inside builder stacks, allowing builders to internalize MEV flows.", "extras": {"Block Construction Authority": "Partial (internal bundle generation)", "Censorship or Filtering Policies": "Builder-specific", "Estimated Validator Coverage": "Medium (varies by builder share)", "Governance Influence Vector": "Private / Opaque", "Infrastructure Control": "Centralized (per-builder)", "MEV Subsector Type": "Searcher Infrastructure (Block-Coupled)", "Operational Role": "Searcher systems operated directly by block builders to source and internalize MEV opportunities.", "Practitioner Validation Check": "If builder-native searchers disappeared, MEV would re-externalize to independent searchers, changing builder economics.", "Practitioner’s Note": "Builder-native searchers concentrate MEV power and reduce open competition between independent searchers.", "Primary MEV Types Enabled": "Arbitrage, liquidations, internalized MEV", "Protocol Influence Surface": "Medium", "Reason for Inclusion": "- Directly generates bundles that shape block contents\n- Tight coupling to block construction authority", "Single-Point-of-Failure Risk": "Medium", "Transaction Ordering Control": "Conditional (internal to builder stack)", "Validator Access Path": "Indirect via owning builder", "Vertical Integration Flag": "Yes"}, "source_label": "MEV & Block Builders"}'::jsonb),
  ('flashbots-integrated-stack', 'Flashbots (Integrated Stack)', 'core-protocol-architecture', 'mev-block-builders', 'https://www.flashbots.net/', ARRAY[]::text[], ARRAY[]::text[], '{"description": "The most influential integrated MEV stack in Ethereum, setting technical and social defaults for how MEV flows from searchers to validators.", "extras": {"Block Construction Authority": "Full (via builder) + Gatekeeping (via relay)", "Censorship or Filtering Policies": "Policy-driven (historically OFAC-aligned at relay layer; evolving)", "Estimated Validator Coverage": "Large (historically dominant)", "Governance Influence Vector": "Corporate + Ecosystem norms", "Infrastructure Control": "Centralized (core stack), open participation at edges", "MEV Subsector Type": "Integrated MEV Stack", "Operational Role": "End-to-end MEV infrastructure spanning searcher bundle pipelines, block building, and relay-mediated validator access.", "Practitioner Validation Check": "If Flashbots’ integrated stack disappeared, MEV pipelines would fragment, validator economics would shift sharply, and new coordination equilibria would be forced.", "Practitioner’s Note": "Flashbots’ power is structural: defaults, formats, and adoption matter as much as market share.", "Primary MEV Types Enabled": "Arbitrage, liquidations, backrunning, bundle-based MEV", "Protocol Influence Surface": "High (MEV-Boost standards, PBS norms)", "Reason for Inclusion": "- Constructs blocks\n- Gates validator access\n- Operates dominant searcher pipelines\n- Directly shapes transaction ordering at the protocol boundary", "Single-Point-of-Failure Risk": "High", "Transaction Ordering Control": "Full (end-to-end influence across the pipeline)", "Validator Access Path": "Relay-mediated (MEV-Boost) with ecosystem defaults", "Vertical Integration Flag": "Yes (Searcher + Builder + Relay)"}, "source_label": "MEV & Block Builders"}'::jsonb),
