  ('builder-relay-integrated-operators-aggregated', 'Builder-Relay Integrated Operators (Aggregated)', 'core-protocol-architecture', 'mev-block-builders', 'N/A', ARRAY[]::text[], ARRAY[]::text[], '{"description": "Vertically integrated MEV operators that combine searcher, builder, and relay roles to reduce competition and capture MEV internally.", "extras": {"Block Construction Authority": "Full + Gatekeeping", "Censorship or Filtering Policies": "Opaque / operator-specific", "Estimated Validator Coverage": "Small–Medium (varies by operator)", "Governance Influence Vector": "Private / Opaque", "Infrastructure Control": "Centralized (per operator)", "MEV Subsector Type": "Integrated MEV Stack", "Operational Role": "Builders that also operate private relays and internal searcher pipelines to internalize MEV.", "Practitioner Validation Check": "If these operators disappeared, MEV would re-externalize, increasing open competition but reducing builder margins.", "Practitioner’s Note": "This category represents the natural economic tendency toward MEV centralization absent countervailing protocol design.", "Primary MEV Types Enabled": "Internalized arbitrage, liquidations", "Protocol Influence Surface": "Medium", "Reason for Inclusion": "- Operate across the full MEV pipeline\n- Directly influence transaction ordering pre-finalization", "Single-Point-of-Failure Risk": "Medium", "Transaction Ordering Control": "Full (internalized)", "Validator Access Path": "Direct + Relay-mediated (private relationships)", "Vertical Integration Flag": "Yes"}, "source_label": "MEV & Block Builders"}'::jsonb),
  ('london', 'London', 'core-protocol-architecture', 'network-upgrades', NULL, ARRAY[]::text[], ARRAY[]::text[], '{"description": "Introduced Ethereum’s new fee market, replacing first-price auctions with a base-fee-plus-tip model and introducing ETH burning.", "extras": {"Activation Date / Epoch": "5 August 2021", "Backward Compatibility": "No (hard fork)", "Client Coordination Required": "Execution clients + validators", "Key EIPs Introduced": "- EIP-1559 (Base fee + burn)\n- EIP-3198 (BASEFEE opcode)", "Layers Affected": "Execution", "Practitioner Note": "London fundamentally changed how users experience Ethereum and how ETH accrues value.", "Practitioner Validation Check": "If London failed, fee markets would fragment and client divergence would have caused immediate chain instability.", "Primary Change Type": "Economics, UX", "Upgrade Risk Profile": "High (fundamental fee market change)", "Why it mattered (structural)": "- Changed ETH’s monetary dynamics\n- Reduced fee volatility\n- Made gas pricing predictable for users and applications"}, "source_label": "Network Upgrades"}'::jsonb),
  ('the-merge', 'The Merge', 'core-protocol-architecture', 'network-upgrades', NULL, ARRAY[]::text[], ARRAY[]::text[], '{"description": "Transitioned Ethereum from Proof-of-Work to Proof-of-Stake by merging the execution layer with the Beacon Chain consensus layer.", "extras": {"Activation Date / Epoch": "15 September 2022", "Backward Compatibility": "No", "Client Coordination Required": "Consensus clients + Execution clients + Validators", "Key EIPs Introduced": "- EIP-3675 (PoS transition)", "Layers Affected": "Consensus + Execution", "Practitioner Note": "The Merge proved Ethereum could execute a high-risk architectural transition without halting the network.", "Practitioner Validation Check": "Failure would have resulted in chain splits, stalled finality, or loss of trust in Ethereum’s upgrade process.", "Primary Change Type": "Architecture, Security, Energy", "Upgrade Risk Profile": "Very High (largest protocol change in Ethereum history)", "Why it mattered (structural)": "- Replaced miners with validators\n- Reduced energy usage by ~99.9%\n- Enabled future scaling via modular design"}, "source_label": "Network Upgrades"}'::jsonb),
  ('shanghai-capella-shapella', 'Shanghai / Capella (Shapella)', 'core-protocol-architecture', 'network-upgrades', NULL, ARRAY[]::text[], ARRAY[]::text[], '{"description": "Enabled withdrawals of staked ETH, completing the PoS transition lifecycle.", "extras": {"Activation Date / Epoch": "12 April 2023", "Backward Compatibility": "No", "Client Coordination Required": "Consensus + Execution clients", "Key EIPs Introduced": "- EIP-4895 (Validator withdrawals)", "Layers Affected": "Execution (Shanghai), Consensus (Capella)", "Practitioner Note": "Contrary to fears, withdrawals did not destabilize staking participation.", "Practitioner Validation Check": "Failure would have frozen validator exits and undermined confidence in PoS economics.", "Primary Change Type": "UX, Economics", "Upgrade Risk Profile": "Medium", "Why it mattered (structural)": "- Removed lock-up risk for validators\n- Enabled staking liquidity and institutional participation\n- Validated PoS as sustainable long-term security model"}, "source_label": "Network Upgrades"}'::jsonb),
  ('dencun', 'Dencun', 'core-protocol-architecture', 'network-upgrades', NULL, ARRAY[]::text[], ARRAY[]::text[], '{"description": "Introduced blobs for rollup data, dramatically reducing L2 fees and shifting scaling focus to data availability.", "extras": {"Activation Date / Epoch": "13 March 2024", "Backward Compatibility": "No", "Client Coordination Required": "Consensus + Execution clients", "Key EIPs Introduced": "- EIP-4844 (Proto-Danksharding / Blobs)", "Layers Affected": "Consensus + Execution", "Practitioner Note": "Dencun quietly delivered one of the largest user-visible fee reductions in Ethereum’s history.", "Practitioner Validation Check": "Failure would have stalled Ethereum’s L2 scaling roadmap.", "Primary Change Type": "Scaling, Data Availability", "Upgrade Risk Profile": "Medium–High", "Why it mattered (structural)": "- Made rollups cheaper and more viable\n- Marked Ethereum’s clear rollup-centric scaling direction\n- Reduced pressure on execution layer"}, "source_label": "Network Upgrades"}'::jsonb),
  ('pectra', 'Pectra', 'core-protocol-architecture', 'network-upgrades', NULL, ARRAY[]::text[], ARRAY[]::text[], '{"description": "Combined Prague (execution) and Electra (consensus) upgrades, improving validator operations and user account functionality.", "extras": {"Activation Date / Epoch": "7 May 2025", "Backward Compatibility": "No", "Client Coordination Required": "Consensus + Execution clients", "Key EIPs Introduced": "- Account abstraction improvements\n- Validator UX enhancements\n- Execution optimizations", "Layers Affected": "Consensus + Execution", "Practitioner Note": "Pectra focused on operability rather than headline scaling.", "Practitioner Validation Check": "Failure would have degraded validator UX and delayed account abstraction progress.", "Primary Change Type": "UX, Staking, Account Architecture", "Upgrade Risk Profile": "Medium", "Why it mattered (structural)": "- Improved validator ergonomics\n- Advanced account abstraction\n- Prepared groundwork for future protocol simplification"}, "source_label": "Network Upgrades"}'::jsonb),
  ('fusaka', 'Fusaka', 'core-protocol-architecture', 'network-upgrades', NULL, ARRAY[]::text[], ARRAY[]::text[], '{"description": "Expanded Ethereum’s data availability capacity and refined execution behavior to better support rollup-centric scaling.", "extras": {"Activation Date / Epoch": "3 December 2025", "Backward Compatibility": "No", "Client Coordination Required": "Consensus + Execution clients", "Key EIPs Introduced": "- PeerDAS and execution refinements\n- Data availability throughput improvements", "Layers Affected": "Consensus + Execution", "Practitioner Note": "Fusaka’s success was measured by its lack of disruption.", "Practitioner Validation Check": "Failure would have delayed scaling capacity and undermined confidence in upgrade cadence.", "Primary Change Type": "Scaling, Infrastructure", "Upgrade Risk Profile": "Medium", "Why it mattered (structural)": "- Increased L2 throughput headroom\n- Reinforced conservative L1 design philosophy\n- Demonstrated upgrade process maturity"}, "source_label": "Network Upgrades"}'::jsonb),
  ('glamsterdam-planned', 'Glamsterdam (Planned)', 'core-protocol-architecture', 'network-upgrades', NULL, ARRAY[]::text[], ARRAY[]::text[], '{"description": "Planned upgrade focusing on block production separation and continued protocol efficiency.", "extras": {"Backward Compatibility": "No", "Client Coordination Required": "Consensus + Execution clients", "Key EIPs Introduced": "- ePBS exploration\n- Further execution optimizations", "Layers Affected": "Consensus + Execution", "Practitioner Note": "Glamsterdam is about refining how blocks are built, not just how many.", "Practitioner Validation Check": "If poorly executed, could destabilize MEV markets and validator incentives.", "Primary Change Type": "Architecture, Scaling", "Upgrade Risk Profile": "N/A", "Why it mattered (structural)": "- Addresses MEV and proposer-builder dynamics\n- Advances protocol modularity"}, "source_label": "Network Upgrades"}'::jsonb),
  ('optimistic-rollup-secured-by-ethereum-with-interactive-fraud-proofs-and-a-fixed-challenge-window-correctness-enforced-via-dispute-resolution-on-l1', 'Optimistic Rollup secured by Ethereum with interactive fraud proofs and a fixed challenge window; correctness enforced via dispute resolution on L1.', 'rollup-scaling-frameworks', 'optimistic-rollups', 'https://arbitrum.io', ARRAY['Arbitrum']::text[], ARRAY[]::text[], '{"description": "An Optimistic Rollup executing transactions off Ethereum L1 and settling state roots back to Ethereum using fraud proofs and a challenge window.", "extras": {"Deployment Model": "Single canonical rollup network; Nitro also supports additional Arbitrum chains.", "Ecosystem Signals (non-app-specific)": "High TVL concentration, sustained transaction throughput, broad developer adoption across DeFi and infra.", "Execution Model": "Single sequencer executes transactions off-chain; batches posted to Ethereum with EVM-equivalent execution.", "Framework Architecture": "Built on Arbitrum Nitro optimistic execution framework.", "Governance & Control": "Protocol upgrades and parameters governed by Arbitrum DAO with multisig safeguards.", "Interoperability": "Ethereum-native settlement; interoperability primarily via bridges and messaging layers outside the protocol.", "Operational Risk": "Single-sequencer reliance; complexity of dispute system; governance coordination risk.", "Practitioner validation check": "If Arbitrum were removed, Ethereum would lose a live optimistic execution environment with its own fraud-proof rules and settlement guarantees.", "Practitioner’s note": "Arbitrum prioritizes high throughput and EVM equivalence, with a complex but mature dispute system. Sequencer decentralization and fraud-proof participation remain active areas of evolution.", "Protocol Ownership": "Core protocol maintained by Offchain Labs; governed by Arbitrum DAO with onchain voting and multisigs.", "Reason for inclusion": "Defines and operates a production Optimistic Rollup with custom fraud-proof logic, sequencer execution rules, and Ethereum-anchored settlement contracts.", "Research & Roadmap": "Focused on fraud-proof decentralization, permissionless validation, and sequencer decentralization.", "Settlement & Finality": "State roots settled optimistically to Ethereum; finality achieved after challenge window expiration."}, "source_label": "Optimistic Rollups"}'::jsonb),
  ('optimistic-rollup-using-fraud-proofs-and-ethereum-l1-settlement-security-assumptions-defined-by-op-stack-contracts', 'Optimistic Rollup using fraud proofs and Ethereum L1 settlement; security assumptions defined by OP Stack contracts.', 'rollup-scaling-frameworks', 'optimistic-rollups', 'https://optimism.io', ARRAY['Optimism']::text[], ARRAY[]::text[], '{"description": "An Optimistic Rollup protocol executing transactions off-chain and relying on fraud proofs with a defined challenge period for Ethereum settlement.", "extras": {"Deployment Model": "Single rollup plus governance-aligned Superchain members.", "Ecosystem Signals (non-app-specific)": "Strong developer momentum; expanding Superchain ecosystem; growing OP Stack adoption.", "Execution Model": "Sequencer-based off-chain execution with EVM equivalence; standardized execution via OP Stack.", "Framework Architecture": "Canonical implementation of the OP Stack framework.", "Governance & Control": "Governed by Optimism Collective (Token House + Citizens’ House); protocol evolution coordinated across OP Stack ecosystem.", "Interoperability": "Designed for Superchain-level coordination; external interoperability handled via bridges.", "Operational Risk": "Shared framework risk across OP Stack chains; sequencer centralization in early stages.", "Practitioner validation check": "If Optimism were removed, a widely adopted optimistic execution standard and its fraud-proof model would cease to exist on Ethereum.", "Practitioner’s note": "Optimism emphasizes simplicity, modularity, and ecosystem standardization. Its influence extends beyond a single chain via the OP Stack.", "Protocol Ownership": "Maintained by Optimism Foundation and governed by the Optimism Collective.", "Reason for inclusion": "Maintains the OP Stack and governs optimistic execution rules, fraud-proof architecture, and sequencing assumptions used in production on mainnet.", "Research & Roadmap": "Standardization of optimistic rollups, Superchain interoperability, and fault-proof maturity.", "Settlement & Finality": "Optimistic settlement to Ethereum with a challenge period before finality."}, "source_label": "Optimistic Rollups"}'::jsonb),
  ('inherits-op-stack-optimistic-security-model-with-fraud-proofs-and-ethereum-settlement-no-custom-security-logic', 'Inherits OP Stack optimistic security model with fraud proofs and Ethereum settlement; no custom security logic.', 'rollup-scaling-frameworks', 'optimistic-rollups', 'https://base.org', ARRAY['Base']::text[], ARRAY[]::text[], '{"description": "A production Optimistic Rollup built on the OP Stack, executing transactions off L1 and settling to Ethereum via optimistic assumptions.", "extras": {"Deployment Model": "Single enterprise-operated rollup.", "Ecosystem Signals (non-app-specific)": "High user onboarding via Coinbase distribution; strong retail transaction volume.", "Execution Model": "Centralized sequencer executing OP Stack transactions off-chain.", "Framework Architecture": "OP Stack–based optimistic execution.", "Governance & Control": "Operated by Coinbase; protocol rules inherited from OP Stack governance rather than Base-specific governance.", "Interoperability": "Ethereum-native; interoperates through standard bridge infrastructure.", "Operational Risk": "Operator centralization; dependency on OP Stack upgrades.", "Practitioner validation check": "If Base were removed, OP Stack optimistic execution would lose a major production deployment validating its assumptions under heavy usage.", "Practitioner’s note": "Base does not define new optimistic mechanics but is a critical real-world implementation testing optimistic rollups at scale under a centralized operator.", "Protocol Ownership": "Operated by Coinbase; protocol rules inherited from OP Stack governance.", "Reason for inclusion": "Operates a canonical Optimistic Rollup mainnet that inherits and enforces OP Stack fraud-proof logic and challenge rules in production.", "Research & Roadmap": "Aligned with OP Stack roadmap; minimal independent protocol research.", "Settlement & Finality": "State commitments posted to Ethereum; finality after OP Stack challenge window."}, "source_label": "Optimistic Rollups"}'::jsonb),
  ('optimistic-rollup-secured-by-ethereum-using-fraud-proofs-modifies-economic-behavior-while-preserving-optimistic-security-guarantees', 'Optimistic Rollup secured by Ethereum using fraud proofs; modifies economic behavior while preserving optimistic security guarantees.', 'rollup-scaling-frameworks', 'optimistic-rollups', 'https://blast.io', ARRAY['Blast']::text[], ARRAY[]::text[], '{"description": "An Optimistic Rollup that executes transactions off Ethereum L1 while embedding native yield mechanics into its execution environment.", "extras": {"Deployment Model": "Single-purpose optimistic rollup.", "Ecosystem Signals (non-app-specific)": "Rapid liquidity onboarding driven by native yield mechanics.", "Execution Model": "Sequencer-driven execution with execution-layer yield mechanisms.", "Framework Architecture": "Optimistic rollup architecture with custom execution-layer economics.", "Governance & Control": "Governed by Blast team and associated governance mechanisms; protocol control more centralized than mature optimistic rollups.", "Interoperability": "Ethereum settlement; interoperability via external bridges.", "Operational Risk": "Higher centralization risk; economic design complexity.", "Practitioner validation check": "If Blast were removed, Ethereum would lose an example of an Optimistic Rollup materially modifying execution incentives while retaining fraud-proof security.", "Practitioner’s note": "Blast demonstrates how optimistic rollups can experiment with execution-level economics while preserving Ethereum settlement guarantees.", "Protocol Ownership": "Controlled by Blast core team; governance less decentralized than mature rollups.", "Reason for inclusion": "Runs production optimistic infrastructure with fraud proofs and challenge windows, modifying economic behavior at the execution layer.", "Research & Roadmap": "Focused on execution-layer economic experimentation rather than core protocol research.", "Settlement & Finality": "Optimistic settlement to Ethereum; finality after standard challenge window."}, "source_label": "Optimistic Rollups"}'::jsonb),
  ('optimistic-rollup-anchored-to-ethereum-relies-on-fraud-proofs-and-challenge-periods-inherited-from-its-optimistic-framework', 'Optimistic Rollup anchored to Ethereum; relies on fraud proofs and challenge periods inherited from its optimistic framework.', 'rollup-scaling-frameworks', 'optimistic-rollups', 'https://unichain.org', ARRAY['Unichain']::text[], ARRAY[]::text[], '{"description": "An Optimistic Rollup purpose-built for Uniswap, executing trades off L1 and settling optimistically to Ethereum.", "extras": {"Deployment Model": "Application-specific rollup.", "Ecosystem Signals (non-app-specific)": "Protocol-aligned liquidity concentration; activity dominated by Uniswap-related flows.", "Execution Model": "Application-oriented sequencer optimized for Uniswap transaction flows.", "Framework Architecture": "Optimistic rollup framework tailored to application needs.", "Governance & Control": "Controlled by Uniswap governance; protocol parameters aligned with application-specific requirements.", "Interoperability": "Ethereum-native; relies on standard cross-chain infrastructure.", "Operational Risk": "High application dependence; limited general-purpose usage.", "Practitioner validation check": "If Unichain were removed, Ethereum would lose a live example of an application-native optimistic rollup with bespoke execution assumptions.", "Practitioner’s note": "Unichain illustrates the convergence between application-specific rollups and canonical optimistic frameworks.", "Protocol Ownership": "Governed by Uniswap governance; protocol control tied to application objectives.", "Reason for inclusion": "Implements optimistic execution and settlement logic tailored to a specific application while retaining fraud-proof guarantees.", "Research & Roadmap": "Focused on application-optimized execution rather than generalized scaling research.", "Settlement & Finality": "Optimistic settlement to Ethereum with delayed finality pending fraud challenges."}, "source_label": "Optimistic Rollups"}'::jsonb),
  ('defines-standardized-optimistic-security-architecture-including-fraud-proof-contracts-and-settlement-logic-for-ethereum-anchored-rollups', 'Defines standardized optimistic security architecture including fraud-proof contracts and settlement logic for Ethereum-anchored rollups.', 'rollup-scaling-frameworks', 'optimistic-rollups', 'https://optimism.io/op-stack', ARRAY['OP Stack (Framework)']::text[], ARRAY[]::text[], '{"description": "A modular Optimistic Rollup framework defining standardized execution, sequencing, and fraud-proof logic for Ethereum-anchored rollups.", "extras": {"Deployment Model": "Reusable framework supporting multiple rollup deployments.", "Ecosystem Signals (non-app-specific)": "Widespread adoption across multiple rollups; increasing standardization signal.", "Execution Model": "Modular execution framework specifying sequencer behavior, batching, and EVM execution semantics.", "Framework Architecture": "Modular optimistic execution, standardized contracts, configurable components.", "Governance & Control": "Governed by Optimism Collective; changes propagate across all OP Stack–based rollups.", "Interoperability": "Enables Superchain-native interoperability; external interoperability via bridges.", "Operational Risk": "Framework-level risk propagates to all dependent rollups.", "Practitioner validation check": "Nitro reflects a performance-oriented approach to optimistic execution, prioritizing throughput and EVM fidelity.", "Practitioner’s note": "OP Stack is best viewed as protocol infrastructure rather than a single chain. Its design choices propagate across the ecosystem.", "Protocol Ownership": "Owned and governed by Optimism Collective.", "Reason for inclusion": "Defines optimistic execution standards used by multiple production rollups, materially shaping how fraud proofs and settlement operate.", "Research & Roadmap": "Core focus on fault proofs, shared sequencing, and Superchain coordination.", "Settlement & Finality": "Defines how dependent rollups post state roots and resolve disputes on Ethereum."}, "source_label": "Optimistic Rollups"}'::jsonb),
  ('defines-arbitrum-s-optimistic-security-model-including-dispute-resolution-and-fraud-proof-mechanics', 'Defines Arbitrum’s optimistic security model, including dispute resolution and fraud-proof mechanics.', 'rollup-scaling-frameworks', 'optimistic-rollups', 'https://docs.arbitrum.io/nitro', ARRAY['Arbitrum Nitro (Framework)']::text[], ARRAY[]::text[], '{"description": "Arbitrum’s core Optimistic Rollup execution framework, defining state transition logic, batching, and fraud-proof mechanics.", "extras": {"Deployment Model": "Reusable framework for Arbitrum-based rollups.", "Ecosystem Signals (non-app-specific)": "High performance adoption within Arbitrum ecosystem.", "Execution Model": "High-performance optimistic execution engine providing EVM equivalence and efficient batching.", "Framework Architecture": "High-throughput optimistic execution engine with EVM equivalence.", "Governance & Control": "Controlled by Offchain Labs and Arbitrum governance; protocol changes affect all Nitro-based rollups.", "Interoperability": "Ethereum-native settlement; no native cross-rollup messaging layer.", "Operational Risk": "Shared framework risk across Nitro-based rollups.", "Practitioner validation check": "If Nitro were removed, Arbitrum’s optimistic execution and fraud-proof model would no longer function.", "Practitioner’s note": "If OP Stack were removed, multiple optimistic rollups would lose their execution framework and fraud-proof rule set.", "Protocol Ownership": "Maintained by Offchain Labs with governance oversight from Arbitrum DAO.", "Reason for inclusion": "Materially defines how optimistic execution and dispute resolution function on Arbitrum-based rollups.", "Research & Roadmap": "Performance optimization, fraud-proof improvements, validator decentralization.", "Settlement & Finality": "Specifies how Arbitrum rollups optimistically settle to Ethereum and reach finality after challenges."}, "source_label": "Optimistic Rollups"}'::jsonb),
  ('primarily-stewarded-by-the-core-zksync-development-organization-matter-labs-historically-with-governance-structures-evolving-over-time', 'Primarily stewarded by the core zkSync development organization (Matter Labs historically), with governance structures evolving over time.', 'rollup-scaling-frameworks', 'zk-rollups', 'https://zksync.io', ARRAY['Yes: via ZK Stack (multi-chain', 'appchain-style deployments).']::text[], ARRAY[]::text[], '{"description": "Ethereum L2 validity (ZK) rollup executing transactions off L1 and proving state transitions to Ethereum via validity proofs (zk-SNARK–based).", "extras": {"Cost Sensitivity to Usage": "Fees tend to be sensitive to:\n- L1 costs (data posting)\n- Prover load (heavy bursts can raise marginal cost/latency)\n- Batch efficiency and compression", "Decentralization Roadmap Credibility": "Assess via concrete milestones: sequencer decentralization, prover decentralization, reduced admin powers, and measurable permissionlessness. (Generally in-progress rather than “complete.”)", "Dependency on External Bridges": "For interoperability beyond the zkSync ecosystem, dependency on external bridges/messaging layers remains typical.", "Developer Adoption Signal": "Developer traction indicated by: ecosystem tooling maturity, documentation, wallet/exchange integrations, and breadth of deployed contracts (avoid app cherry-picking; focus on infra adoption).", "Ecosystem Dependency Risk": "Dependency concentration on:\n- sequencer/prover operators\n- core team for upgrades\n- ZK Stack ecosystem coupling (if building within their multi-chain vision)", "Emergency Controls": "Commonly includes pause / emergency intervention capabilities (exact scope depends on contract configuration).", "Enterprise / Institutional Orientation": "Moderate-to-strong positioning for scalable, low-latency settlement with cryptographic guarantees; actual enterprise adoption depends on compliance tooling and counterparties.", "Ethereum Composability Model": "Composability with Ethereum is asynchronous (bridged and finalized via L1 settlement), not synchronous L1-style composability.", "Ethereum Settlement Path": "L2 batches → state commitments + validity proofs → L1 verification contract → finalized L2 state anchored to Ethereum.", "Execution Environment": "EVM-compatible (supports Solidity tooling patterns; not typically positioned as strict EVM equivalence).", "Is This a Network or a Framework": "Both:\n- Network: zkSync Era (live L2)\n- Framework: ZK Stack (deploy additional zk-chains)", "Mainnet Maturity": "Production mainnet with ongoing upgrades; maturity should be assessed by uptime history, incident response, and stability of core APIs/bridges.", "Native Cross-Rollup Support": "Native interoperability is strongest within the ZK Stack / zkSync multi-chain vision (if you build inside that family). Cross-ecosystem interoperability is not “native” at the protocol layer.", "Opinionated vs Modular Design": "Generally modular, but opinionated in core choices (VM approach, proof system, upgrade patterns).", "Permissioned vs Permissionless Deployment": "Varies by the specific chain: mainnet operation and framework usage frequently begin more permissioned, with permissionlessness typically a roadmap deliverable (verify current state per chain).", "Practitioner’s Note": "If zkSync were removed, Ethereum would lose an operational ZK rollup whose validity-proof system and Ethereum-verified settlement enforce L2 state correctness.", "Proof System Type": "SNARK-based", "Prover Architecture": "Typically permissioned / operator-led proving in practice; decentralization is generally roadmap-driven rather than fully realized in early-to-mid lifecycle ZK rollups.", "Prover Bottlenecks": "- Specialized hardware requirements (compute-heavy proving)\n- Centralization risk if proving remains permissioned\n- Latency sensitivity: proving time can dominate “time to finality”", "Proving Cost Characteristics": "Mix of high fixed costs (prover infrastructure) plus usage-based costs (more activity → more proving demand + L1 posting).", "Reason for Inclusion": "Ships production ZK rollup infrastructure where state correctness is enforced by validity proofs verified on Ethereum, making it a canonical ZK Rollup execution framework.", "Reorg / Failure Handling Model": "- Post-L1 finalization: effectively no L2 reorg risk beyond Ethereum finality\n- Pre-L1 proof verification: “soft finality” risk is tied to sequencer/prover behavior and operational incidents", "Reusable by Other Rollups": "Yes, via ZK Stack (teams can launch zk-chains using the stack).", "Security Inheritance from Ethereum": "Full settlement security from Ethereum once proofs are verified and state updates are finalized on L1.", "Sequencer Model": "Commonly single sequencer today with stated paths toward decentralization (sequencer decentralization remains a key roadmap item across ZK rollups).", "Shared Prover / Sequencer Assumptions": "May be shared or separate depending on deployment model; practitioners should verify whether a given zk-chain shares proving/sequencing infrastructure or runs independently.", "Single Canonical Rollup": "Yes: zkSync Era as the primary canonical network.", "State Transition Definition": "Defined by zkSync protocol implementation and upgrade process (i.e., the protocol team/governance controls the canonical rules). Changes require protocol upgrades.", "Throughput Constraints": "Bounded by:\n- Prover capacity (compute throughput)\n- L1 posting constraints (data published to Ethereum)\n- Sequencer throughput and state growth", "Time to Cryptographic Finality": "Final when validity proof is verified on Ethereum and the state update is finalized (practically: usually minutes-to-hours depending on batching/proving cadence and L1 conditions).", "Trust Assumptions Beyond Ethereum": "- Soundness/correctness of circuits and prover implementation\n- Trusted setup assumptions if the specific SNARK system requires it (common in SNARK-based systems)\n- L2 operator assumptions for “soft finality” before L1 verification (sequencer/prover liveness)", "Upgrade Authority": "Typically admin-controlled upgrades (multisig/DAO-controlled contracts depending on the current governance state). Practitioners should treat upgrade control as a first-class risk dimension.", "Validity Proof Model": "Validity proofs are generated per batches; proof aggregation/recursion may be used to improve efficiency (implementation-specific and evolves over time).", "Verifier Location": "Ethereum L1 smart contracts verify proofs and accept finalized state commitments.", "Withdrawal Latency": "Withdrawals are gated by L1 finalization of the proven state (often materially faster than optimistic challenge-window withdrawals; exact latency depends on the rollup’s batching/proving cadence and bridge design).", "ZK Rollup": "zkSync"}, "source_label": "ZK Rollups"}'::jsonb)
) AS v(slug, name, sector_slug, subsector_slug, website, chains, tags, meta)
JOIN public.sectors sec ON sec.slug = v.sector_slug
JOIN public.subsectors s ON s.sector_id = sec.id AND s.slug = v.subsector_slug
ON CONFLICT (slug) DO UPDATE SET
  name = EXCLUDED.name,
  subsector_id = EXCLUDED.subsector_id,
  website = EXCLUDED.website,
  chains = EXCLUDED.chains,
  tags = EXCLUDED.tags,
  meta = EXCLUDED.meta,
  updated_at = NOW();
